quests[46665] = { id = 46665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[46666] = { id = 46666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Motherlode", description = "Pst... Come 'ere! I just got a tip about a cave on this island that is a treasure trove of loot! This could be my biggest score yet.\n\nProblem is, I uhh... sprained my ankle. Yeah, I would be right there with you battling those demons to get this treasure, but I shouldn't be putting any weight on this leg of mine. Shucks.\n\nHow about you go check on this cave and report back to me. I'll mark your map where the cave entrance is. I've been told it's pretty hidden, so you've got to look around.", progress = "You find anything?", completion = "Looks like we hit the motherlode! Now all we need is a key... Huh. Why don't you go work on getting some keys for these chests and I'll hang out with goofy-nose here.", objectives = "Investigate the cave that Excavator Karla told you about.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46674] = { id = 46674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Preservation of Nature", description = "I fear this attack on Goldrinn is only the beginning, {name}. Whoever is ordering these attacks must be found and defeated.\n\nWasn't Thisalee with you? She never returned... brash child. I assume she is already on the Broken Shore, trying to track down this commander. Please, find her. Do not let her take this on alone.", completion = "Look at him squirm. He gave in easily!", objectives = "Find Thisalee Crow near Deliverance Point on Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46675] = { id = 46675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Track a Demon", description = "I took the initiative to scout around before I grabbed that wyrmtongue. It seems like their forces are holed up in a camp in Impsorrow Approach. What I've struggled to figure out, however, is who their commander is and if he's nearby.\n\nIf he's leading from elsewhere, the troops need to have some commands on them. Let's go see if we can find any... on their dead bodies!", progress = "Collecting some missives should allow me to figure out the commander's position.", completion = "Let me take a look at these... I think I've got it!", objectives = "Collect 3 Impsorrow Missives from demons in Impsorrow Approach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46676] = { id = 46676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nature's Touch", description = "Apparently we're not the only druids that have run into these demons. The Legion took a ton of captives and brought them back to their camp. Our brothers and sisters lay wounded and hurting...\n\nYou can heal! Let's go save them!", progress = "We can't let the other druids suffer any longer!", completion = "I feel a lot better knowing we were able to save some of the other druids. We did what we could.", objectives = "Heal 5 Injured Druids in Impsorrow Approach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46677] = { id = 46677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prick of a Thistle", description = "Their commander's name is Katith'rax. He's the one who organized these attacks, and now the one who leads them. Luckily, it doesn't seem as though he's far off.\n\nRight off the coast is a small island. Seems as though he hides there, barking orders without getting his hands dirty.\n\nI, on the other hand, enjoy getting my hands a little dirty. Don't you?", progress = "This guy is going to pay for what he's done!", completion = "Revenge feels so good.\n\nBut stopping the attacks on the ancients feels even better.", objectives = "Kill Commander Katith'rax on Darkstone Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46678] = { id = 46678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of the Threads", description = "Tailoring is the noblest of professions because clothing is universal. Most dress with nary a thought. If you analyze the legends, some races stand out from all others. \n\nThe Nightborne are masters of style! Much of the brilliance is in their materials--in particular their thread and their looms. We will take advantage of both. Before you gather materials, I need to confirm my list. Find the fashion treatise I brought with me. Perhaps I dropped it by the flight master?", progress = "I need a copy of Nights with the Nightborne so we can focus our efforts. I probably left it on my flight over.", completion = "Ah thank you for locating that. Let me see--we'll want to target the most stylish of the Nightborne... this seems like the perfect list... oh, she's dangerous... so's that one... very well. \n\nThere is a lot to do so you should get started!", objectives = "Bring Eliezer his lost copy of Nights with the Nightborne", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46679] = { id = 46679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thread of Shadow", description = "Vandros of the Nightborne. There is an elf who knows how to dress. Ever since he was a young noble in the Court of Farondis, Vandros has been known for snappy, fashion forward outfits. \n\nI've never been able to see his garments up close but my research tells me that his tailor's technique is not so much in the fabric as it is in the thread. It appears to be spun of the very shadows themselves. \n\nYou have your methods to obtain it, I'm sure. Get his robes and get the thread.", progress = "Vandros maybe be difficult to defeat but we really need that shadow thread from his robes.", completion = "Excellent, {name}! Oh the things you will sew!", objectives = "Defeat Advisor Vandros in the Arcway in Mythic difficulty and extract Shadow Thread from his robes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46680] = { id = 46680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thread of Starlight", description = "Melandrus of the Nightborne is First Blade of Elisande. Perhaps you've heard of him? He is a great hero to the Nightborne but, to be absolutely honest, he is a mess with regards to style. \n\nHis accoutrements are somewhat better and a particular pair or bracers are rather nice. In fact, the thead that binds them will be absolutely perfect for your pending outfits. Why don't you get that for me and we will talk further.", progress = "Did you get the thread from Melandrus' Star-Touched Bracers?", completion = "Excellent work, my friend! I will find an appropriate use for this as soon as I can.", objectives = "Defeat Advisor Melandrus in the Court of Stars and extract Starlight Thread from his bracers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46681] = { id = 46681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thread of Souls", description = "Have you ever had a chance to lay eyes on Elisande, Grand Magistrix of the Nightborne? Stunning! Fashion-forward! Nice posture! \n\nYou'd do well to take a page from her book! In fact, you'd tell well to take the thread from her Suramari Soul Wraps! These hold great symbolic value to her people so it's doubtful she will give them willingly. \n\nSo be it, take her out and get that thread.", progress = "Grand Magistrix Elisande's Soul Wraps  have the most beautiful thread! I don't meant to be pushy but... I'm waiting.", completion = "The soul thread is so beautiful! I am very pleased, {name}.", objectives = "Defeat Grand Magistrix Elisande in the Nighthold and extract Soul Thread from her wraps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46682] = { id = 46682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drapings of the Ancients", description = "{name}, we are going to need a high quality cloth to work with. Thankfully, the weaving quality of nightborne craftspeople from long ago was very good. It is a lost art to some degree but I feel like you can take their masterworks and do even more with it. \n\nSome of the hostiles in these parts still wear Ancient Imbued Silkweave Armor. Start to unstitch the silkweave cloth from any of that armor that you find on Broken Shore.", progress = "Keep your eye out for Ancient Imbued Silkweave. We need a lot of it to start making fabulous things.", completion = "Ah, that is just what we need, young {race}!", objectives = "Obtain 100 Ancient Imbued Silkweave from humanoids in Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46683] = { id = 46683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starweave and Shadowcloth", description = "At last, you are ready for true tailoring knowledge. I truly think you've earned it. \n\nI've fashioned the materials you've gathered into a satchel of Legendary Tailor's Materials. \n\nGo to the Queen's Grace Loom and weave two bolts of cloth. With my careful research of fashion, heroes, and legends. I believe the new cloth you will make will echo through the ages. Hurry!", progress = "Please make a bolt of Starweave and a bolt of Shadowcloth at the loom as soon as you can and bring it back to me for final inspection.", completion = "The cloth you've created is like none I've ever seen. Beautiful! \n\nTake these elements and make something wonderful with them. I will be the first to write of your accomplishments and I truly believe you will become, at last, an icon of heroic style, {name}!", objectives = "Make a bolt of Starweave and a bolt of Shadowcloth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46684] = { id = 46684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of the Elderhide", description = "Leatherworking is one of the oldest forms of craftsmanship in the world. Hides of animals were the first clothing. Legends tell of a particular form of leather curing that has been lost to us in modern times. \n\nCombining magic of the earth with some of the finest leathers ever found, this technique has been recreated by yours truly through careful analysis and my understanding of style. \n\nTo begin, you must capture some ancient wisps to channel the exact nature magic for the curing process.", progress = "Have you found an Ancient Wisp?", completion = "Ancient wisps? Beautiful! This is a strong start, {name}.", objectives = "Capture Ancient Wisps in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46685] = { id = 46685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wisp and the Shadow", description = "{name}, have you heard of the nightmare lord, Xavius, whose shade haunts Darkheart Thicket? I have heard that this shade is sometimes seen wearing a colorless shroud. \n\nThis shroud is steeped in powerful magic and the wisp will draw it out for you. \n\nIf you can fight the shade, take the shroud, and use your skills to dye it, I will show you how to work wonders!", progress = "Have you obtained and dyed the shroud yet? Make your way to Darkheart Thicket and get it done.", completion = "The shroud is perfect, {name}. Well done!", objectives = "Defeat the Shade of Xavius in Darkheart Thicket on Mythic Difficulty and dye his shroud.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46686] = { id = 46686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wisp and the Sea", description = "Queen Azshara and her handmaidens are the subjects of many a tragic tale. Her power and her hubris lead her badly astray but, even so, her handmaidens are loyal to her to this day. There is power in such a thing.\n\nThe Wrath of Azshara is an abomination but, truthfully, it is actually one of her handmaidens who willingly gave her life to protect her queen. Few know this. The Ancient Wisp knows this truth and if you take it to battle the Wrath of Azshara, you may find the handmaiden's gloves. Restore them.", progress = "You need to battle the Wrath of Azshara and find and restore a pair of handmaiden's gloves.", completion = "These gloves have an air of sadness about them, do they not? Regardless, thank you for restoring them and bringing them here.", objectives = "Retrieve the Waterlogged Handmaiden's Gloves from the Wrath of Azshara on Mythic Difficulty, then treat them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46687] = { id = 46687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wisp and the Nightmare", description = "Xavius, the Nightmare Lord in Val'Sharah, derives some of his power from his spellsash. It is enchanted and tied to the world beneath his feet and cannot be removed from his body. \n\nHowever, with the ancient wisp's help, the spellsash can be removed if you can but defeat Xavius in combat. Trivial for one of your skill, I'm sure. \n\nTake the wisp to the Emerald Nightmare, take the spellsash, and use your skills to repair any damage you've caused in the battle.", progress = "{name}, defeat Xavius and obtain his spellsash for me. Make sure that it is repaired to perfect condition!", completion = "The spellsash looks perfect, {name}! I couldn't have done a better repair myself.", objectives = "Get the spellsash from Xavius in the Emerald Nightmare and repair it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46688] = { id = 46688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leather of the Ancients", description = "{name}, we are going to need high quality leather to work with. Ancient Dreadleather is the best hereabouts and local tanning techniques were exceptional in the past. To the untrained eye, it may look like normal dreadleather. That is where the wisp comes in. \n\nMany of your enemies across Broken Shore will have some amount of Ancient Dreadleather.  As you defeat them, you will start to recognize armor made from it and you can harvest the leather for our purposes.", progress = "Keep your eye out for ancient dreadleather. We will need a good amount for our purposes.", completion = "That is, indeed, dreadleather. Should be enough for our needs, {name}. My thanks!", objectives = "Obtain 100 pieces of Ancient Dreadleather from humanoids in Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46689] = { id = 46689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisp-Touched Elderhide", description = "Dreadleather, with knowledge carefully reverse-engineered from ancient texts, can be worked into elderhide. It is partly a matter of advanced craftsmanship and partly a simple magic of the earth. \n\nWith the ancient wisps you caught and the materials you've captured and the research I have done, I have put together a Legendary Tanner's Kit for you. Take it to the heirloom hides of Hrul Sharptooth in Thunder Totem. The wisp will help you use the kit there to create Elderhide.", progress = "Hrul Sharptooth has hides in his dwelling in Thunder Totem. When you approach them, you will be able to use your kit. Bring it back to me for final inspection.", completion = "The Elderhide leather that you've created is magnificent. Take this, and work your magic to create something of wonder and beauty. \n\nIt is an extraordinary accomplishment and you will look quite dashing--and I should know!", objectives = "Use the Legendary Tanner's Kit in Hrul Sharptooth's dwelling in Thunder Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46690] = { id = 46690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of the Wardenscale", description = "One of my favorite legends is of the Father of Owls on Isle of the Watchers. It is said that his spirit comes to comfort his creatures during times of trouble. \n\nWith the Legion's arrival on the Isle of Watchers, many of the owls are being slain so you can find him there. \n\nWe need to \"borrow\" him for a short time as he has seen many of the battles where famous warriors and villains have worn armor made of Wardenscale. With his spirit, you can identify items we can extract it from and use it for style!", progress = "Have you captured the Father of Owls yet?", completion = "What a magnificent creature! Allow me to attune him to you...there! With his ancient knowledge, we are ready to begin.", objectives = "Capture the Father of Owls on the Isle of the Watchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46691] = { id = 46691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Owl and the Traitor", description = "I've scoured the tales and legends for armor that might have Wardenscale components and one Cordana Felsong is a name that caught my attention. \n\nEvidently she has a family mantle that has what we need. Kill her and find it on her traitor's corpse. The owl will make sure that you spot it. \n\nIt is likely chipped from years of hard use so restore it to prime condition and bring it back to me.", progress = "Have you gotten Cordana's mantle and restored it yet? Rumor has it she is in the Vault of the Wardens.", completion = "The mantle looks brand new! Excellent craftsmanship, {name}!", objectives = "Find and repair Cordana Felsong's Mantle in the Vault of the Wardens in Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46692] = { id = 46692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Owl and the Dreadlord", description = "The demon Mephistroth is one of the most powerful of the Nathrezim--the dreadlords. I can see in your eyes that you know what I am going to ask you to do. But it is for your own good! You can't keep wandering the lands looking like you do. \n\nMost recently, Mephistroth has been dispatched by the Legion to the Cathedral of Eternal Night. No doubt, he will be wearing some legplates that I believe contain Wardenscale. Take them, shine them up, and bring them to me.", progress = "Have you defeated Mephistroth and added some shine to his legplates?", completion = "Those legplates are rather large! I'm surprised you survived that encounter--and you've refinished them beautifully!", objectives = "Find and restore the Legplates of Mephistroth by defeating him in the Cathedral of Eternal Night in Mythic Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46693] = { id = 46693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Owl and the Observer", description = "I've researched some foul creatures in my time but Viz'aduum the Watcher may top the list. I mean, he is a giant, disgusting, dangerous eyeball! \n\nCurrently he haunts Karazhan--do you know the place? In Medivh's time, much of our common knowledge was stored there. Alas, the time has passed... \n\nI digress. Viz'aduum is in possession of armor from the First War--bracers to be specific--and they are incredibly valuable. It pains me but take them, repair them, and then we must use their wardenscale.", progress = "Have you killed that horrible beast and brought me the Bracers of the First War?", completion = "These bracers have legends of their own--too bad we need to sacrifice them to build a proper reputation for you but we all must suffer for fashion. \n\nI would also like to personally thank you for killing Viz'aduum. It just shouldn't... exist. I mean... well you know what I mean.", objectives = "Kill Viz'aduum in the Return to Karazhan dungeon on Mythic difficulty, and retrieve and repair the Bracers of the First War.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46694] = { id = 46694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mail of the Ancients", description = "There is some wardenscale scattered here and there in the Broken Isles. Various enemies and local monsters seeking to ape the superior races like ourselves will have picked it up and worn it. \n\nThe kind we need is amongst the oldest ever made. It is ancient gravenscale. Keep all that you find and and bring it to me. We will harvest what useful bits we can from it.", progress = "Do you have the Ancient Gravenscale that we need?", completion = "That should be enough Ancient Gravenscale. Well done, {name}!", objectives = "Obtain 100 Ancient Gravenscale from humanoids in Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46695] = { id = 46695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prime Wardenscale", description = "I feel like it is finally time for use to create something truly remarkable. To create the armor that will set you apart from the rest, we need to make the best wardenscale. \n\nFind the nightelf, Celea, in Azsuna. She has attuned and sanctified the ground where she waits to focus the magic of our world and only there can you make what we need. Go with speed, {name}.", progress = "Have you found Celea in Azsuna and prepared the Wardenscale beside her? It will only work at that spot. Bring it back to me when you have finished.", completion = "The Wardenscale is incredibly light yet strong--I have never seen its equal. {name}, there is nothing else I can do. It is all up to you now. \n\nTake what you have earned and make wonders with it. Stylish, stylish wonders.", objectives = "Find Celea in Azsuna and create the Wardenscale where the magic aligns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46696] = { id = 46696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of the Four Hammers", description = "{name}, we should be honest with each other before we begin. You are a blacksmith by trade and this a noble profession. Yet I value style and fashion. Heavy armor and weapons create a certain bulkiness in a hero's profile that I think does no service whatsoever to the cut of one's clothes. \n\nFret not--I can at least teach you something about taste in finer materials. \n\nGo to Dalaran and find a book translated by my brother about 3 forgotten heroes. We will find the finest metals ever forged!", progress = "Did you find that dusty old tome of Fafnir's? I have to admit that he may have found something interesting in it.", completion = "Ah, the book! Let's see... blah, blah, blah, 3 heroes... blah, blah, blah, forge 3 hammers and create the ultimate hammer... blah, blah, blah, forger will be metaphorically crushed and possibly literally killed under impossible expectations, etc. Looks good! \n\nIt appears I can help you find what remains of the armor and weapons of these heroes and these incredible materials can be used to make amazing things!", objectives = "Go to Dalaran and find the Legend of the Four Hammers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46697] = { id = 46697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Godfighter", description = "The Godfighter championed the mortals against what he saw as oppression and abuse by immortal beings. The legends say the gods feared him but he did fall in time. \n\nMy research shows that the gods he fought were the gods of Stormheim. Odyn, in particular. The Godfighter's shield took so much damage from lightning bolts that it became lightningsteel. After the Godfighter died, Odyn took the shield and melted it down as a trophy. Get that lightningsteel from him and forge a hammer from it.", progress = "Have you taken the white lightningsteel from Odyn and forged it into a hammer?", completion = "What a remarkable metal! I feel like it tingles just to hold it. Incredible!", objectives = "Take White Lightningsteel from Odyn in the Halls of Valor in Mythic difficulty and forge it into a hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46698] = { id = 46698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dragonhunter", description = "The Dragonhunter lived in a time before history was written and her tale was passed down orally to us. \n\nIt seems that dragons tormented her people and after her village temple was destroyed, she rallied the local tribes, became a queen and killed all of the dragons. She was then banished for some reason and wandered until her death, alone. What proves the story is a piece of draconic slag from left over from a metal idol in her birth village. Dargul the Underking has it now. Forge a hammer from it.", progress = "Did you find the draconic slag from the Dragonhunter's birth village temple? When you do, forge a hammer from it.", completion = "It is a powerful magic that kept the draconic slag hot so many years later. Is it the will of the Dragonhunter? Was dragon fire even more dangerous in ancient times?  Or was it actually the dragon Neltharion, whom you know as Deathwing, whom she fought back then? \n\nI wonder if I shall ever find out. \n\nWell done! The hammer is extraordinary.", objectives = "Defeat Dargul in Neltharion's Lair in Mythic difficulty and create a hammer from his Red-Hot Draconic Slag", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46699] = { id = 46699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hellslayer", description = "The Hellslayer's tale is a classic story of revenge. Odyn wished to take the souls of the bravest as champions but Helya sent her kvaldir to take the souls first. The people of Stormheim suffered as their pawns. \n\nThe kvaldir came to the Hellslayer's ship at night and killed her son and took his soul to serve Helya for eternity. The Hellslayer took up her axe and the spear of her son and sought vengeance. Finish her quest. Defeat Helya and forge a hammer from the Frostveined Shale.", progress = "The Frostveined Shale is what remains of the Hellslayer's weapons after they were destroyed on Helya's cold forge. It is powerful stuff and we need it.", completion = "The hammer is perfect but rather cold. I do respect your craftsmanship!", objectives = "Defeat Helya and forge a hammer from the Frostveined Shale in the Trial of Valor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46700] = { id = 46700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armor of the Ancients", description = "It is not just the hammers and my careful research that we need, {name}. We also need a lot of the very highest quality of ancient metal to make the final hammer. \n\nEnemies across Broken Shore that are able to wear armor often collect bits of Ancient Demonsteel here and there. Collect enough of it in your battles for our purposes.", progress = "Do you have the Ancient Demonsteel that we need?", completion = "That will be enough for our needs. Good work, {name}!", objectives = "Obtain 100 Ancient Demonsteel from humanoids in Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46701] = { id = 46701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammer of Forgotten Heroes", description = "{name}, this is exciting, I have to admit. I've put everything you've gathered into this chest of supplies and the only place with the power and magic to handle the creation of the final hammer is the Firmament Stone. I believe that blacksmiths of your rarified skills will know it? \n\nI realize that there are dwarf stereotypes out there about smithing but I really don't care for all of the banging and heat. Suppose that is why I followed the scholarly path. Good luck to you!", progress = "Be sure to take the chest of supplies I've given you to the Firmament Stone and forge the final hammer. Bring it back to me for inspection when you have done so.", completion = "The Hammer is possibly the most perfect item you have ever forged. With this, you will create armor of such style and taste that you will become a figure of legends. \n\nI'm proud of you, {name}. I'm so happy you will finally start to look good.", objectives = "Go to the Firmament Stone in Highmountain and forge the Hammer of Forgotten Heroes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46705] = { id = 46705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retaliation", description = "Of course I will help you! Although to be honest, I am not certain where a new arcane shield generator can be found these days. So many of our craftspeople have been executed... I will think on it.\n\nWould you mind helping me as well? I have been observing a nearby group of Felborne for some time. Their activities have become increasingly brazen of late.\n\nI think it's time to teach them how it feels to be violently suppressed.", completion = "Revenge is so sweet. Thank you.", objectives = "Kill 7 Felborne Insurgents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46707] = { id = 46707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minion! Kill That One Too!" }
quests[46709] = { id = 46709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready for Crafted Legendary" }
quests[46717] = { id = 46717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[46719] = { id = 46719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amal'thazad's Message", description = "Deathlord, Amal'thazad has requested your presence at Acherus.\n\nHe has been in contact with the Lich King, and making improvements on the citadel.\n\nFor his benefit, or yours, I know not.", completion = "Ah, Deathlord, you have returned.\n\nI have inscribed a series of frozen runes above Acherus. Once attuned, you will be able to communicate with the Lich King more... completely.\n\nHe will be able to show you things he could not before.\n\n<Amal'thazad emits a horrible, rasping noise, that you can only assume is a chuckle.>", objectives = "Speak with Amal'thazad in Acherus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46720] = { id = 46720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frozen Memories", description = "Close your eyes, Deathlord. Can't you feel his presence already?\n\n<The Lich King's icy presence is inside your mind in an instant.>\n\nStand in the rune circle atop Acherus, Deathlord.\n\nI will show you what I have seen.\n\n<The presence fades.>", objectives = "Take the portal to the top of Acherus, listen to the Lich King's plan, then witness his vision in Icecrown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46721] = { id = 46721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sulfuron Hammer" }
quests[46722] = { id = 46722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing Up My Sleeve", description = "Now, you may think that a sack of gold would be a good reward for your troubles, but I've got something better in mind for you.\n\nI'm gonna teach you my best trick!\n\nI know, I know, I'm a very generous goblin.   Let me show you how it's done!", progress = "You gonna do the trick or not?", completion = "This is a catastrophe! Something must be wrong with my rabbit dimension!\n\nOkay, I'm gonna need your help again.", objectives = "Use Akazamzarak's Hat to perform a magic trick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46723] = { id = 46723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down the Rabbit Hole", description = "Alright, bub. I'm gonna need you to go in there and find out what's going wrong.  I'd go in myself, but... well, it's complicated.\n\nAnyway, we got no time to lose! Just jump in the hat and find out what's goin on.\n\nI'll be ready to pull you out once you've got everything handled.", progress = "Don't just stand there, get in the hat and help the poor bunnies!", completion = "I can't believe a wolf got in my pocket dimension! That's the last time I order a crate of rabbits from Moonbrook!\n\nI owe you a solid, bud. Here, take my spare hat. Just don't go trying to muscle in on my Dalaran business, got it?", objectives = "Enter Akazamzarak's Hat and find out what's happening to his rabbits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46724] = { id = 46724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: The Great Akazamzarak", description = "You know, you're a useful <fella/dame> to have around, {name}. \n\nTell ya what, I think I'll accompany you on your adventures. Seems to be good gold in it, and I think it'll be a good way to scout out some new business opportunities around the Broken Isles.\n\nWhat do you say?You will learn:", objectives = "You know, you're a useful fella to have around, {name}. \n\nTell ya what, I think I'll accompany you on your adventures. Seems to be good gold in it, and I think it'll be a good way to scout out some new business opportunities around the Broken Isles.\n\nWhat do you say?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46725] = { id = 46725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Outage", description = "Kor'vass asked for a bunch of other stuff, but it won't hurt her to learn a bit of patience. Don't you agree?\n\nShe did mentioned that the ship'ss weaponss array is severely damaged and dangerously low on power. Knowing her, I'm sure that'ss an exaggeration.\n\nI suppose you may as well take this power core I confiscated. You can replenish it from those disgusting Legion geyserss and energy globess floating around the Tomb.", completion = "I alwayss hated heightss. I'm glad you're the one who has to do the dirty work.", objectives = "Refill the Fel Hammer's Power Core with fel energy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46727] = { id = 46727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth: Tides of War", description = "Champion!\n\nAn urgent War Council is underway. Your presence is requested in Stormwind Keep.", progress = "Thank you for coming.", completion = "The Horde have forced our hand yet again.\n\nThis cannot stand.", objectives = "Attend the War Council in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46728] = { id = 46728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nation of Kul Tiras", description = "Kul Tiras is the greatest naval power in Azeroth, and a former ally. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was defeated at Theramore.\n\nMany have criticized Jaina's decision that day, saying she believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father.\n\nPerhaps she feels the time has come to atone for this.\n\nLoath as I am to put Jaina in harm's way... Kul Tiras must join the Alliance.\n\nGood luck.", completion = "Home again, after all this time.", objectives = "Speak with Lady Jaina Proudmoore in Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46729] = { id = 46729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Old Knight", description = "These days Cyrus is the Harbormaster, but he used to be one of Daelin Proudmoore's most trusted knights!\n\nI lost my mother when the Scourge hit Lordaeron. My father sent me here to be raised away from the war. I don't know much about him... just that he was a Stormwind knight who gave his life fighting the Lich King.\n\nDaelin hand-picked Cyrus to raise me and forced him to take a desk job. It's the only reason he wasn't at Theramore.\n\nHe's probably checking in that other Alliance ship. Let's go!", progress = "Sorry, I should have mentioned he can be a bit... long-winded at times.", completion = "I've never seen Cyrus fired up like this!\n\nSounds like we have work to do.", objectives = "Meet with Cyrus Crestfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46730] = { id = 46730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armies of Legionfall", description = "Thanks to your leadership, the {class} order has grown even mightier than I had dared hope. Alongside champions of the other orders, we now have a fighting force capable of driving the Burning Legion from our world.\n\nIt's time to end this invasion! Using the Pillars of Creation, we will dissipate the Felstorm and seal the Tomb of Sargeras.", completion = "Our forces are assembled. We are ready to begin.", objectives = "Escort Archmage Khadgar at Krasus' Landing in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46732] = { id = 46732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prophet's Gambit", description = "I can feel their presence just ahead. It is as faint as the lightest breeze that once rolled across these hills, but it is not of the Legion, of that I am certain.\n\nWe must see if these broken are potential allies. It is a great risk, but our numbers are too few to ignore the chance.", completion = "Turalyon yet lives! Perhaps there is still hope after all.", objectives = "Follow Prophet Velen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46733] = { id = 46733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion Expansion Started Tracking Quest" }
quests[46734] = { id = 46734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Broken Shore", description = "It has been a long and costly war, {name}. It is time we put an end to it.\n\nWe will drive the Burning Legion from their seat of power and close their gateway into Azeroth. Our first step is to gain a foothold on the Broken Shore.\n\nDivided, the Alliance and Horde faced defeat. But united as the Armies of Legionfall, we will claim victory!", completion = "Mephistroth is on the run, and we have a foothold here at Deliverance Point.\n\nA good start, I'd say, though we still have much to do.", objectives = "Complete the Assault on Broken Shore scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46735] = { id = 46735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contribute to Command Center" }
quests[46736] = { id = 46736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contribute to Nether Disruptor" }
quests[46743] = { id = 46743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies From Highmountain", description = "Champion, your help to our people has far exceeded any of our expectations, and has provided us some much needed breathing space.\n\nPlease, take these supplies to aid you in the war against the Legion. With your continued aid, we should be able to gather more and prepare them for you.", completion = "Champion, your help to our people has far exceeded any of our expectations, and has provided us some much needed breathing space.\n\nPlease, take these supplies to aid you in the war against the Legion. With your continued aid, we should be able to gather more and prepare them for you.", objectives = "Speak with Ransa Greyfeather in Highmountain for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46744] = { id = 46744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greater Power for Greater Threats", description = "{name}, the war against the Legion grows in intensity beyond what we have imagined. It is critical that we increase our strength to match that of our foes.\n\nIt is imperative that you strengthen your artifact as much as possible. It is the only way you can stay ahead of the threat the Legion poses.", progress = "Is your artifact as powerful as you can make it?", completion = "Excellent! Your artifact is as powerful as you can make it... for now.\n\nWe are working on a solution for that, but in the meantime you should continue your efforts on the Broken Shore.", objectives = "Unlock all traits on any of your artifact weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46745] = { id = 46745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies From the Court", description = "Prince Farondis has asked me to thank you for your continued efforts to aid our lands.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", completion = "Prince Farondis has asked me to thank you for your continued efforts to aid our lands.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", objectives = "Speak with Veredis Fallon in Azsuna for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46746] = { id = 46746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies From the Valarjar", description = "Greetings, little hero.\n\nThe mighty Odyn has proclaimed that you should receive these gifts of war. At every turn you continue to prove your valor and your efforts to aid the Valarjar have not gone unnoticed. \n\nFor the Valarjar! For Odyn! For {name}!", completion = "Greetings, little hero.\n\nThe mighty Odyn has proclaimed that you should receive these gifts of war. At every turn you continue to prove your valor and your efforts to aid the Valarjar have not gone unnoticed. \n\nFor the Valarjar! For Odyn! For {name}!", objectives = "Speak with Valdemar Stormseeker in Stormheim for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46747] = { id = 46747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies From the Dreamweavers", description = "Hero! \n\nYour dedication to defending Val'sharah has given us a much needed respite from the vile influence of the Legion. We were able to scavenge some supplies as a result of your efforts. \n\nHere, take them and know that, should you continue to aid us, we will set aside more rewards such as these as we find them.", completion = "Hero! \n\nYour dedication to defending Val'sharah has given us a much needed respite from the vile influence of the Legion. We were able to scavenge some supplies as a result of your efforts. \n\nHere, take them and know that, should you continue to aid us, we will set aside more rewards such as these as we find them.", objectives = "Speak with Sylvia Hartshorn in Val'sharah for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46748] = { id = 46748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies From the Nightfallen", description = "Outlander, I have some supplies for you. These goods are yours, earned by your continued efforts to our forces here in Suramar.\n\nI shall set aside similar treasures should you choose to aid our people more.\n\nYou have my deepest thanks.", completion = "Outlander, I have some supplies for you. These goods are yours, earned by your continued efforts to our forces here in Suramar.\n\nI shall set aside similar treasures should you choose to aid our people more.\n\nYou have my deepest thanks.", objectives = "Speak with First Arcanist Thalyssra in Suramar for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46749] = { id = 46749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies From the Wardens", description = "Your dedication to our efforts has yielded results. We have supplies for you.\n\nContinue your dedication and there will be more.", completion = "Your dedication to our efforts has yielded results. We have supplies for you.\n\nContinue your dedication and there will be more.", objectives = "Speak with Marin Bladewing in Azsuna for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
