quests[46764] = { id = 46764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enable Challenge Boss Fights" }
quests[46765] = { id = 46765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Shore: Investigating the Legion", description = "While we focus efforts on the Broken Shore, we must be careful to guard against other threats. We have been getting disturbing reports on the Legion starting or supporting indirect threats to Azeroth.\n\nWhile you are on the Broken Shore, please keep an eye out for strange objects or intelligence that could give us a clue as to what and where these threats are.\n\nI know it is not a lot to go on, we will do our best from here as well.", progress = "Found something?", completion = "This scroll, fascinating... this confirms our concerns about indirect Legion threats. We must return to Dalaran, {name}!", objectives = "Discover a hidden Legion threat while on the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46766] = { id = 46766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ulgthax" }
quests[46767] = { id = 46767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maximillian 1 Week Cooldown" }
quests[46768] = { id = 46768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akazamzarak 1 Week Cooldown" }
quests[46769] = { id = 46769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relieved of Their Valuables", description = "Not all demons on this shore stomp around in the open. Some slink about in the shadows, finding more subtle ways to advance the Legion's cause.\n\nI have been observing the behavior of smaller demons, these wyrmtongues. They seem to spend considerable time acquiring objects of power. We cannot allow them to use these items against us.\n\nThe wyrmtongues stash their goods in chests spread around the Broken Shore. I suggest you relieve them of their ill-gotten gain.", progress = "Have you found the wyrmtongue caches?", completion = "Fine work. It's important to keep powerful treasures out of demon hands.\n\nThere are more ways to undermine the Legion's agenda than simply killing demons... although there's a lot to be said for good old-fashioned violence.", objectives = "Find 3 Hidden Wyrmtongue Caches on the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46772] = { id = 46772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mage Tower", description = "Well done {name}. In testament to the efforts of all forces fighting here, we have come together to complete the construction of the Mage Tower.\n\nAll that remains is for you to inspect our work, and complete the construction.", progress = "Inspect the {class} Tower, and complete its construction.", completion = "Our grand efforts have resulted in a boon which all can leverage in the coming days.", objectives = "Complete the construction of the Mage Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46773] = { id = 46773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Command Center", description = "Well done {name}. In testament to the efforts of all forces fighting here, we have come together to complete the construction of the Command Center.\n\nAll that remains is for you to inspect our work, and complete the construction.", progress = "Inspect the Command Center, and complete its construction.", completion = "Our grand efforts have resulted in a boon which all can leverage in the coming days.", objectives = "Complete the construction of the Command Center.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46774] = { id = 46774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nether Disruptor", description = "Well done {name}. In testament to the efforts of all forces fighting here, we have come together to complete the construction of the Nether Disruptor.\n\nAll that remains is for you to inspect our work, and complete the construction.", progress = "Inspect the Nether Disruptor, and complete its construction.", completion = "Our grand efforts have resulted in a boon which all can leverage in the coming days.", objectives = "Complete the construction of the Nether Disruptor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
