quests[46777] = { id = 46777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bounties of Legionfall", description = "{class}t, thanks to your efforts, our forces have been able to secure additional resources from the battlefield.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare.", completion = "Battlelord, thanks to your efforts, our forces have been able to secure additional resources from the battlefield.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare.", objectives = "Speak with Captain Ruysantos on the Broken Shore for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
