quests[46792] = { id = 46792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering of the Storms", description = "Thunderaan has asked me to send you to the Throne of the Four Winds to assist him with a situation.\n\nSpeak with me again when you're ready to leave, Farseer.", progress = "I'm sure the Windlord's problem won't be too difficult for you to assist with.", completion = "Now that the council is reunited, the plane of air shall flow as one again!\n\nI believe Windlord Thunderaan has a reward waiting for you.", objectives = "Speak with Consular Celestos to begin the Gathering of the Storms scenario. Complete the scenario and return to Celestos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46793] = { id = 46793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Broken Shore - Buildings - Mage Tower - Buff Activation - Tracking Quest" }
quests[46794] = { id = 46794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Court", description = "The grateful Court of Farondis has requested your presence. They wish to reward you for your exceptional aid.", completion = "Greetings Deathlord {name}.\n\nFor some time now you have been a Paragon to our prince and to our people. Our gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of our gratitude and a share in the spoils of war. The more you aid us, the more we can provide you.", objectives = "Speak with Veridis Fallon in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
