quests[46796] = { id = 46796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of Highmountain", description = "The grateful Highmountain Tribes have requested your presence. They wish to reward you for your exceptional aid.", completion = "Greetings Huntmaster {name}.\n\nFor some time now you have been a Paragon to our people. Our gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of our gratitude and a share in the spoils of war. The more you aid us, the more we can provide you.", objectives = "Speak with Ransa Greyfeather in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46797] = { id = 46797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Dreamweavers", description = "The grateful druids of the Dreamweavers have requested your presence. They wish to reward you for your exceptional aid.", completion = "Greetings Highlord {name}.\n\nFor some time now you have been a Paragon to Nature and to our people. Our gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of our gratitude and a share in the spoils of war. The more you aid us, the more we can provide you.", objectives = "Speak with Sylvia Hartshorn in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46798] = { id = 46798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Valarjar", description = "The impressed vrykul of the Valarjar have requested your presence. They wish to reward you for your exceptional aid.", completion = "Greetings Highlord {name}.\n\nFor some time now you have been a Paragon to Odyn and a hero to the Valarjar. Our gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of our gratitude and a share in the spoils of war. The more you aid us, the more we can provide you.", objectives = "Speak with Valdemar Stormseeker in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46799] = { id = 46799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Nightfallen", description = "A very grateful Thalyssra has requested your presence. She wishes to reward you for your exceptional aid.", completion = "Greetings outlander, liberator, Huntmaster, friend.\n\n.Our gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of our gratitude and a share in the spoils of war. The more you aid us, the more we can provide you.", objectives = "Speak with First Arcanist Thalyssra in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46800] = { id = 46800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Wardens", description = "The impressed Wardens have requested your presence. They wish to reward you for your exceptional aid.", completion = "Greetings Huntmaster.\n\nFor some time now you have been a Paragon in your efforts against the Legion and your aid of the Wardens. Our gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of our gratitude and a share in the spoils of war. The more you aid us, the more we can provide you.", objectives = "Speak with Marin Bladewing in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46801] = { id = 46801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ship - Val'sharah" }
quests[46802] = { id = 46802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Legionfall Armies", description = "Your loyal forces in the Armies of Legionfall have requested your presence. They wish to reward you for your exceptional aid.", completion = "Greetings, Deathlord.\n\nFor some time now you have been a paragon in your efforts against the Legion, the beacon that unites our armies together. Our gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of our gratitude and a share in the spoils of war. The more you aid us, the more we can provide you.", objectives = "Speak with Captain Ruysantos on the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46804] = { id = 46804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fashion History and a Philosophy of Style", description = "Greetings, {name}. I am a fashion historian and I have astonishing advancements in tailoring, leatherworking, and blacksmithing that I must share with you. Why? \n\nA true legend is only as good as their ability to form an epic silhouette on the battlefield and--let's be honest--this is not where you shine. \n\nSpeak to me again if you wish to learn.", progress = "Let me know when you are ready to begin your education. You sorely need it!", completion = "Glad I could share the Hammerbeard System of Style and Taste with you. Are you ready to work for your legacy in your chosen profession?", objectives = "Learn from Eliezer Hammerbeard how to create \"flair and drama\" in your wardrobe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46805] = { id = 46805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deceiver's Downfall", description = "Once he was as a brother to me. Then he bartered the soul of my world for his own power. Hounded my people across the stars. Twisted my son into a monster.\n\nNow he has come to oversee the final assault on Azeroth. To end this world as he has countless others.\n\nKil'jaeden.\n\nWe must ensure he does not escape our grasp this time, {name}. Storm the tomb. Break the Legion's hold. End the Deceiver's reign.", progress = "Give no quarter. The Deceiver must fall.", completion = "When we faced the Deceiver, millennia of rage flooded my heart. Hatred took hold, blinding me to every thought but revenge.\n\nThankfully the Light helped me see that the future must not be defined by vengeance, but by hope. Your courage showed me that as well, {name}.\n\nIn those last moments of Kil'jaeden's life, I had to let go of the past. Not only for my own sake, but for the memory of my son.\n\nMy spirit and mind are clear and focused. Now we take the fight to Sargeras himself. Now we end the Legion.", objectives = "Enter the Tomb of Sargeras and defeat Kil'jaeden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46808] = { id = 46808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ship - Highmountain" }
quests[46809] = { id = 46809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivering Lost Knowledge", description = "The very nature of this ancient night elf tome causes the book to seek out knowledge. This could prove to be a serious boon to your efforts to research your artifact weapon.\n\nI'd wager the scholars in your order hall would find it of great use, possibly unlocking new avenues of empowerment.\n\nI suggest you take it to them immediately. We need every advantage possible against the Legion!", completion = "What have you brought today, Deathlord?\n\n<Illanna examines the ancient tome.>\n\nThis book... it changes everything!", objectives = "Speak with the artifact researcher in your class order hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46810] = { id = 46810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Forge It Goes...", description = "This cloak is too tattered to be usable, but can be obliterated at the Obliterum Forge in Dalaran.", progress = "Visit the forge recently?", completion = "If you find any other unwanted spoils of war, obliterate them at the forge and I can help you find something more desirable.", objectives = "Take the Gladiator's Tattered Cloak to the Obliterum Forge in Dalaran and use the forge to obliterate it, then take the result to Marshal Frazer in Greyfang Enclave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46811] = { id = 46811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broodmother's Wrath" }
quests[46812] = { id = 46812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconic Secrets", description = "<The Lich King's icy presence enters your mind once more.>\n\nArthas never found the prize he sought, Deathlord.\n\nIt is ours by right.\n\nThe dragons must know where the resting place of their kin resides.\n\nFind a member of the bronze flight, the tenders of history. Do not be merciful.\n\n<The presence fades.>", objectives = "Interrogate Trizormu in Wyrmrest Temple in Dragonblight, then follow the Lich King's plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46813] = { id = 46813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Glacier", description = "<The Lich King's presence is overwhelming.>\n\nDo you know why the red dragonflight seeks to prevent us from finding our prize?\n\nThe bones of a great red dragon teem with the essence of life, even decades after its passing.\n\nYou will consume this life essence, blight it, and turn it to undeath.\n\nAnd then you will raise a dragon.\n\nFly now into the north. Find this glacier, and your destiny.\n\n<The presence fades.>", progress = "Go, now, and find your frozen destiny.", completion = "<A crack in the ice beneath the snow, it's very deep. You feel the unholy power surge within you, this would be the ideal location to unleash the energy to raise the dragon.>", objectives = "Travel to the Lost Glacier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46814] = { id = 46814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Frostwyrm" }
quests[46815] = { id = 46815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eredath, Jewel of Argus", description = "The shattered ruin below us is all that remains of Eredath.\n\nWe called it the Jewel of Argus. It was here that my fellows in the triumvirate guided our people to prosperity. That was a long time ago.\n\n<Velen lapses into a moment of silence.>\n\nJoin me on the surface. We will begin our search for the Crown of the Triumvirate.", completion = "It is as if the battle never ceased. How long have they suffered like this?", objectives = "Descend to Eredath with Velen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46816] = { id = 46816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rendezvous", description = "There is much to be done before this nightmare can end, but we need to regroup before we draw more attention from the Legion.\n\nI managed to retain a signal crystal during the crash used to call transport beacons from the Xenedar.\n\nWith luck, we should be able to use it to establish a link between here and your forces as well.", progress = "We must establish a link to your vessel before we can press on.", completion = "Lothraxion is an old friend, and a noble warrior. We are fortunate to have him among us.", objectives = "Use the Signal Crystal to call down a Lightforged Beacon from the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46817] = { id = 46817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infernal Downfall" }
quests[46818] = { id = 46818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defenseless and Afraid", description = "This is the battle that raged while I awaited the Genedar. So many ran to join me, but Kil'jaeden inspired still more to stand in their way.\n\nMy people were slaughtered without mercy.\n\nTo cover our retreat I ordered for this arena's defenses to be activated. It is clear that they were unable.\n\nTo turn the tide in this battle, to give these spirits rest, we must do what they could not. Find a way to activate the pylons.", progress = "I will hold this position. The spirits may be only echoes of their former selves, but they do not know that.", completion = "The tide is turning. We must press forward.", objectives = "Collect Stolen Pylon Cores from enemies in Triumvirate's End and use them to activate 3 Ancient Pylons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46819] = { id = 46819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrecked Cart" }
quests[46820] = { id = 46820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
