quests[46825] = { id = 46825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mud Mucking" }
quests[46826] = { id = 46826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battleplate of the Silver Hand" }
quests[46827] = { id = 46827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meld Into the Shadows", description = "We should meet back up with the rest of the council and tell them of what we have achieved this day. At your leisure, return to us. We shall be waiting.", completion = "We've been discussing your recent success, {name}. We walk the shadows, and that often goes taken for granted. But without us, the Armies of Legionfall would have a great many more powerful demons to deal with.\n\nWe do not need the fame. We reap the rewards.", objectives = "Return to the Hall of Shadows, and meet Lord Jorach Ravenholdt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46829] = { id = 46829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Abuse" }
quests[46830] = { id = 46830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlefield" }
quests[46831] = { id = 46831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Village" }
quests[46832] = { id = 46832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aalgen Point", description = "You wanna hold territory on this chunder puddle of an island, right? Right. That means linkin' up with camps on the outskirts, mate. \n\nI know this bloke called Heidirk. Scrappy fella, loves to get into the thick of it. Headed out to the eastern coast with those drakes of his.\n\nHave a look for him. Remind him he owes me a pint or two!", completion = "Chambers sent you? He can down a tankard with the best of 'em, I'll give him that. But if he says I owe him anything, he's a liar!\n\nDon't you worry, my drakes and I will hold the point here. But more of this shore will need to be secured before your campaign can find victory.", objectives = "Speak with Heidirk the Scalekeeper at Aalgen Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46833] = { id = 46833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nature Unshackled" }
quests[46834] = { id = 46834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khazaduum, First of His Name", description = "The Argunite Matrix that powered this part of Eredath was shattered by a hulking beast. We had never seen another like him.\n\nHe was called Khazaduum and he was a most faithful servant of the Legion. He volunteered to undergo an experimental transformation to become the first of his kind. His arrival was the end of this battle.\n\nAs a prize he took the Argunite Keystone from the shattered matrix. Take it back and we can finally end this bloodshed.", progress = "Please, they should not be made to suffer any longer.", completion = "I cannot right every wrong that happened here, but this is a comfort nonetheless.\n\nThank you, {name}.", objectives = "Retrieve the Argunite Keystone from the Echo of Khazaduum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46835] = { id = 46835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers of a Frightened World Tracking" }
quests[46839] = { id = 46839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Darkness", description = "I'm afraid it's only a matter of time before our presence is known.\n\nWe must begin our preparations at once.", completion = "So it begins.", objectives = "Walk with High Exarch Turalyon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46840] = { id = 46840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoners No More", description = "Hatuun's people have endured arduous times. Their numbers dwindle as those ripped from beyond the walls of their sanctuary become servants to the annihilan lords in the pits just beyond, sentenced to a life of labor, torture and ultimately, death.\n\nSeek out these captives, release them from their bonds and show our allies we stand as one against the Burning Legion.", completion = "Hatuun's people will greatly appreciate what you've done for them.", objectives = "Rescue 10 Darkfallen Slaves from the Annihilan Pits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46841] = { id = 46841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat Reduction", description = "In time, Hatuun and his people will set aside their bitterness and become valuable allies. But their trust must be earned.\n\nHe says their village is beset by a demon called Aggonar and his cruel kin.\n\nWe need these fiends out of the way before we can seek out Alleria and the others.\n\nThe chieftain lent us his horn. Use it to call down his people's vengeance upon the demon lieutenants while I carve a path to Aggonar's lair.", progress = "Has the threat been dealt with?", completion = "Now that their lords have been reduced to ash, we may strike at the heart of their power.", objectives = "Slay Kar'aaz, Xeth'tal, and Magraloth in the Annihilan Pits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46842] = { id = 46842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strike at the Heart", description = "These pits have long been a blight upon the lives of our new allies. The demons hunt them down and torture the poor souls for sport.\n\n<Turalyon shakes his head with disgust, fixing his gaze upon the beast before him.>\n\nIt is time to make them pay for their cruelty and restore hope to this Light-forsaken place.\n\nWe strike on your mark, {name}.", progress = "No rest until the deed is done.", completion = "This victory is only the first link in a long chain, Slayer.", objectives = "Slay Aggonar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46843] = { id = 46843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Vindicaar", description = "That pit lord won't trouble our new allies any longer.\n\n<Turalyon's brow furrows.>\n\nUntil another takes its place, at least. If there's one thing I've learned in our endless war against the Legion, it's to savor victories as you find them.\n\nCome, let us take a moment to regroup back at your vessel. Alleria and I have been waiting a long time for a reunion with our son.", completion = "Our absence has wounded Arator. We knew it would. But we had to know that he was safe while we fought the Legion.\n\nNow that we are reunited, I will not let us be separated again.", objectives = "Return to the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46844] = { id = 46844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cathedral of Eternal Night: Mistress of Blades" }
quests[46845] = { id = 46845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance Point", description = "On my way here, I ran across a squad of demon hunters headed northwest to Vengeance Point. You can bet the Legion will try to stop them from establishing a forward position.\n\nI spoke to an elf named Izal Whitemoon. Not the friendliest sort, but I'm sure she'd be grateful if you lent the Illidari a hand... whether she admits it or not.", progress = "This siege is disabling my bats from their scouting duties.", completion = "The Illidari don't waste time on congratulations. There is more to do, and you're the one to do it.\n\nGet a move on.", objectives = "Defeat the Legion siege on Vengeance Point and report to Izal Whitemoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46846] = { id = 46846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Word of Zul", description = "I have a mundane task for you. Our esteemed Prophet Zul has words to distribute to very specific individuals in de port. \n\nAnd he requested you be de one to deliver dem.\n\nDon't ask me why he didn't just have you deliver these when you were here de first time. De prophet is notorious for not sharing all of his visions.", progress = "Have you finished all of your deliveries?", completion = "Ah, you are a competent errand-{race} after all. Perhaps you could be trusted with more important tasks. Like trash removal.", objectives = "Deliver the Words of Zul to various individuals in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46865] = { id = 46865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cathedral of Eternal Night: Mother of Flame" }
quests[46866] = { id = 46866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torture Chamber" }
quests[46867] = { id = 46867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cathedral of Eternal Night: Fel Beast" }
quests[46868] = { id = 46868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cathedral of Eternal Night: Infernal Dead" }
quests[46869] = { id = 46869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cathedral of Eternal Night: Temptress of Pain" }
quests[46870] = { id = 46870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Broken Shore - Buildings - Command Center - Buff Activation - Tracking Quest" }
quests[46871] = { id = 46871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Broken Shore - Buildings - Nether Disruptor - Buff Activation - Tracking Quest" }
quests[46904] = { id = 46904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boon of the Command Center", objectives = "Well done, I can now provide you with a boon that will grant you a benefit while the Command Center is activated.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46924] = { id = 46924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wolf's Tale", description = "Goldrinn sure didn't take any time getting out of here, did he?\n\nLet's go see if we can find him outside.", completion = "We must warn the Dreamgrove of what is happening.", objectives = "Find Goldrinn outside of the Stormrage Barrow Dens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46926] = { id = 46926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shakedown", description = "Where are de guards? \n\nPrincess Talanji has convinced King Rastakhan to permit outsiders in our port. For de first time in centuries, we have allowed non-trolls to set foot on our shores and peddle their wares.\n\nAnd now trolls of lesser tribes seem to think dey can take advantage of these merchants?\n\nI will not allow dis sort of behavior. While I investigate why de merchants are not protected, I want you to work your way through de bazaar and slay any thugs you find. \n\nSend dem a message.", progress = "If Zuldazar is to once again be a shining jewel, we must learn to work with de other races.", completion = "You have my thanks. I think having someone of de Horde dispense dis justice was extra fitting.\n\nDe fact dat we have left our harbor so unprotected worries me greatly.", objectives = "Slay 15 Dockside Ruffians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46927] = { id = 46927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Punishment of Tal'aman", description = "Look, Zolani is going about dis all wrong. If you want de Amani, or anyone, to pay attention, take out their leaders.\n\nGo into Tal'aman and look for their mighty gong. Challenge four of their disciples to combat and slay dem.", progress = "De forest trolls can be mighty mean.", completion = "It will not be long before these disciples are replaced with new ones. Hopefully, de next ones will learn from de past.", objectives = "Challenge 4 Amani Disciples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46928] = { id = 46928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Punishment of Tal'farrak", description = "De Sandfury tribe may have had a hand in some crime around here, but it is really their false belief system dat makes dem do dis sort of thing. Enter Tal'farrak, bang de gong within, and face de hydra dey keep as a sacred pet.\n\nBring me dis thing's tongues.", progress = "Did you get de tongues?", completion = "Ha ha ha. You can tell a lot about a tribe by what dey worship.", objectives = "Collect the tongues of Ghaz'ragon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46929] = { id = 46929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deterrent", description = "General Jakra'zet had orders to ensure dis place had protection. Guard protection. I see none of dat.\n\nJakra'zet is a stubborn general, and one I have had my eye on for a while now.\n\nRegardless, we must remind dese lesser tribes who rules dis city with a message dey will understand.\n\nI charge you with collecting heads.\n\nEnter Tal'farrak and Tal'aman, and collect a quota of heads.", progress = "Troll politics are more like a blood sport.", completion = "When visitors do not understand de language of your laws, it becomes necessary to explain your laws in a language dey do understand.", objectives = "Collect 6 Amani Heads from Tal'aman and 6 Sandfury Heads from Tal'farrak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46930] = { id = 46930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rastakhan", description = "You stand before General Jakra'zet, lord of de armies of Zandalar, enforcer of her seas and bringer of war.\n\nAnd I do not like you. \n\nIt took years to earn my place here after your Horde laid waste to my people. You will not undo what I have built.\n\nI will see you kneel before King Rastakhan. I will watch you beg as he lets me take your head for a trophy. I will fling your corpse into de wastes of Vol'dun.\n\nHer \"Highness\" may object... but she is not queen yet.\n\nCome. Let us fly to your fate.", progress = "Welcome, Champion of de Horde. I am King Rastakhan, lord of Zandalar and her peoples.", completion = "Your deeds had reached my ears before your feet ever set foot in my land. It is time we spoke.", objectives = "Meet King Rastakhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46931] = { id = 46931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaker of the Horde", description = "Your Horde has grown powerful, eclipsing some of de troll empires in its magnitude.\n\nFor saving my daughter, you have earned de right to a presence in my city.\n\nSince my daughter has taken such a fondness to you, you may join her in de Great Seal beneath us. De servants there will answer to you now.\n\nTalanji seems excited by whatever she has planned for your people. I look forward to being amused by it later.\n\nZolani can show you a way down dat does not involve falling.", completion = "Welcome to de Vault of Kings, {name}. We move new treasures dat we find into dis room, all because of dis object on de wall.\n\nDis object dates back farther than anything we know. It is my hope dat I can one day discover its true purpose.\n\nI should not keep you, however. I am sure you have pressing business with Princess Talanji.", objectives = "Establish your Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46932] = { id = 46932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tad More Corruption" }
quests[46933] = { id = 46933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felrglrglrglrgl" }
quests[46935] = { id = 46935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow of the Sentinax", description = "This device appears to be used to relay messages to the large demon ship up above. Unfortunately, it is cracked and unresponsive.\n\nPerhaps someone at Deliverance Point will know more about these beacons.", completion = "The Legion uses these beacons to communicate with their fleet up above. If we were to find more of these...", objectives = "Bring the Broken Sentinax Beacon to Warmage Kath'leen in Deliverance Point.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46938] = { id = 46938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alone in the Abyss", description = "Champion, we will suffer the same fate as the Army of the Light if the Legion fires that infernal weapon upon us.\n\nWe must descend into the siege camp below and destroy it while we still can!", completion = "Welcome to Argus, homeworld of the Burning Legion.", objectives = "Speak to Grand Artificer Romuul to disembark the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46939] = { id = 46939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monk Finale" }
quests[46940] = { id = 46940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Using Lost Knowledge", description = "I'm not sure you realize what this tome could mean for us. We can find even more knowledge on your artifacts to help the war effort!\n\nLet's begin immediately. On your command, we stand by to begin researching again.", progress = "Yes, Highlord?", completion = "Excellent! Please check back in a while for a progress update.", objectives = "Start a Research Work Order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46941] = { id = 46941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path Forward", description = "<Velen stares beyond the arena for a time.>\n\nWe must continue on, but I feel Eredath is far from finished with us. We should take advantage of this relative safety while we still can.\n\nI will place a signal beacon that will allow the Vindicaar to lock onto our location. Romuul will send us our means of returning to the Vindicaar if there is a need.", progress = "Much remains to be seen, {name}. Argus has not forgotten us.", completion = "The way forward is clear, and we have the Army of the Light at our side.", objectives = "Call down a Lightforged Beacon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46942] = { id = 46942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cost of Power" }
