quests[46946] = { id = 46946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Forge It Goes...", description = "This cloak is too tattered to be usable, but can be obliterated at the Obliterum Forge in Dalaran.", progress = "Visit the forge recently, have we?", completion = "If you find any other unwanted spoils of war, obliterate them at the forge and I can help you find something more desirable.", objectives = "Take the Gladiator's Tattered Cloak to the Obliterum Forge in Dalaran and use the forge to obliterate it, then take the result to Violet Shadowmend in Winderunner's Sanctuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
