quests[46997] = { id = 46997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boon of the Command Center", objectives = "Well done, I can now provide you with a boon that will grant you a benefit while the Command Center is activated.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
