quests[46999] = { id = 46999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boon of the Command Center", objectives = "Well done, I can now provide you with a boon that will grant you a benefit while the Command Center is activated.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47000] = { id = 47000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Council's Call", description = "I'm sorry that I haven't kept your apprised of the situation. We needed more actionable information before bringing the matter before you.\n\nThe Council of the Six has been investigating Legion threats outside of the Broken Shore. I believe this scroll to be the final piece of information we need.\n\nMeet me in Dalaran at the Violet Citadel. We will need the other members of the Council.", completion = "<Khadgar gives you a knowing nod.>\n\nI'm glad you came, Huntmaster.", objectives = "Seek out the Council of Six in the Violet Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47001] = { id = 47001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Elite 21" }
quests[47002] = { id = 47002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crown of the Triumvirate", description = "We begin our search now, {name}.\n\nThe Crown of the Triumvirate was created to spread the Light's touch to all. With it, our culture thrived.\n\nWhen I fled Argus with the Draenei, I took one shard of the Crown with me to ensure that it would not fall into the wrong hands.\n\n<Velen tips his staff forward and gestures to the central crystal.>\n\nKil'jaeden and Archimonde's fragments are still here. I will seek them out, but you will need to safeguard me while I search.\n\nStay close, my friend.", objectives = "Protect Velen while he locates fragments of the Crown of the Triumvirate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47003] = { id = 47003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoration: The Bradensbrook Investigation", description = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook!\n\nIs it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid.", completion = "A bit late for the warning, eh? Still, I appreciate that we haven't been forgotten.", objectives = "Go to Bradensbrook in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47004] = { id = 47004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoration: The Bradensbrook Investigation", description = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook!\n\nIs it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid.", completion = "A bit late for the warning, eh? Still, I appreciate that we haven't been forgotten.", objectives = "Go to Bradensbrook in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47005] = { id = 47005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistweaver: The Bradensbrook Investigation", description = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook!\n\nIs it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid.", completion = "A bit late for the warning, eh? Still, I appreciate that we haven't been forgotten.", objectives = "Go to Bradensbrook in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47006] = { id = 47006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holy: The Bradensbrook Investigation", description = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook!\n\nIs it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid.", completion = "A bit late for the warning, eh? Still, I appreciate that we haven't been forgotten.", objectives = "Go to Bradensbrook in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
